/* Templates contain no networking or application state mutations. */
var StudioView = (() => {
  const e = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;'}[c]));
  const i = name => icon(name);
  const act = (name, text, cls = 'is-button', attrs = '') => `<button type="button" class="${cls}" data-studio-action="${name}" ${attrs}>${text}</button>`;
  const label = key => StudioModel.styles.find(s => s[0] === key)?.[1] || key || 'Natural';
  const fileMeta = a => `${a.width || '—'} × ${a.height || '—'} · ${StudioModel.filename(a).split('.').pop().toUpperCase()}`;
  function menu(items, title = 'More actions', cls = '') {
    return `<details class="is-menu ${cls}"><summary class="is-button" aria-label="${e(title)}">${title === 'More actions' ? i('more') : e(title)}${title === 'More actions' ? '' : i('chevron')}</summary><div class="is-menu-list">${items}</div></details>`;
  }
  function header(s) {
    return `<header class="is-header"><div><span class="is-eyebrow">CLOUDCORE / CREATIVE WORKSPACE</span><h1>Image Studio<span class="is-title-dot"></span></h1></div>
      <details class="is-menu is-model-menu"><summary class="is-button is-model-info">${i('chip')} Studio info ${i('chevron')}</summary><div class="is-menu-list"><strong>${e(s.capabilities?.model || 'Image engine')}</strong><p>${e(s.capabilities?.message || s.capabilityError || 'Checking engine availability…')}</p><small>Output dimensions depend on your selected format. Generation may take several minutes.</small>${act('refresh-capabilities','Refresh connection','is-text-button')}</div></details></header>
      <nav class="is-nav" role="tablist" aria-label="Image Studio">${[['create','spark','Create'],['remix','sliders','Remix'],['gallery','grid','Gallery'],['analyze','eye','Analyze']].map(([id,ic,t]) => `<button type="button" role="tab" id="is-tab-${id}" aria-selected="${s.tab === id}" aria-controls="is-panel" tabindex="${s.tab === id ? 0 : -1}" data-studio-action="tab" data-tab="${id}">${i(ic)}${t}${id === 'gallery' && s.assets.length ? `<span>${s.assets.length}</span>` : ''}</button>`).join('')}</nav>`;
  }
  function editor(s, remix = false) {
    const d = remix ? s.remix : s.create;
    const mode = remix ? 'remix' : 'create';
    const cap = s.capabilities;
    return `<aside class="is-composer" aria-label="${remix ? 'Remix settings' : 'Image settings'}">
      ${remix ? reference(s) : ''}
      <div class="is-field"><div class="is-label-row"><label for="is-${mode}-prompt">${remix ? 'Describe what to change' : 'Your prompt'}</label><span id="is-prompt-count">${d.prompt.length}/500</span></div>
      <textarea id="is-${mode}-prompt" data-studio-field="prompt" data-draft="${mode}" maxlength="500" rows="5" placeholder="${remix ? 'Keep the composition, change the scene to golden hour…' : 'A quiet glass pavilion in the mountains, soft morning light, architectural photography…'}">${e(d.prompt)}</textarea>
      <div class="is-editor-tools">${act('enhance',`${i('spark')}${s.enhancing ? 'Enhancing…' : 'Enhance'}`,'is-text-button',s.enhancing ? 'disabled' : '')}${d.originalPrompt !== null ? act('undo-enhance','Undo','is-text-button') : ''}
      ${menu(act('inspire',`${i('bulb')} Try an idea`,'is-menu-item') + act('history',`${i('history')} Prompt history`,'is-menu-item') + act('clear-prompt',`${i('close')} Clear prompt`,'is-menu-item'),'Prompt tools')}</div></div>
      <div class="is-field"><label for="is-style">Style</label><select id="is-style" data-studio-field="style" data-draft="${mode}">${StudioModel.styles.map(([id,t,desc]) => `<option value="${id}" ${d.style === id ? 'selected' : ''}>${t} — ${desc}</option>`).join('')}</select></div>
      <div class="is-field"><label for="is-format">Format</label><select id="is-format" data-studio-field="aspectRatio" data-draft="${mode}">${StudioModel.formats.map(([id,t,w,h]) => `<option value="${id}" ${d.aspectRatio === id ? 'selected' : ''}>${t} · ${id} · ${w} × ${h}</option>`).join('')}</select></div>
      ${remix && cap?.controls?.strength ? `<div class="is-field"><div class="is-label-row"><label for="is-strength">Change strength</label><output id="is-strength-value" for="is-strength">${Math.round(d.strength*100)}%</output></div><input id="is-strength" type="range" min="0.1" max="0.9" step="0.05" value="${d.strength}" data-studio-field="strength" data-draft="remix"><div class="is-range-labels"><span>Closer to original</span><span>More change</span></div></div>` : ''}
      <details class="is-advanced" ${d.advanced ? 'open' : ''}><summary>${i('sliders')} Advanced settings ${i('chevron')}</summary><div><div class="is-field"><label for="is-negative">Leave out</label><input id="is-negative" maxlength="500" placeholder="Blurry details, text, watermarks…" data-studio-field="negativePrompt" data-draft="${mode}" value="${e(d.negativePrompt)}"></div><div class="is-field"><label for="is-seed">Seed <span class="is-muted">Optional</span></label><input id="is-seed" type="number" min="1" max="2147483647" placeholder="Random" data-studio-field="seed" data-draft="${mode}" value="${e(d.seed)}"></div></div></details>
      <div id="is-submit-error">${error(s.error)}</div>
      ${remix && cap && !cap.remix ? `<p class="is-notice">${i('help')} ${e(cap.remixMessage || 'Image remix is unavailable on the connected engine.')}</p>` : ''}
      <button type="button" class="is-primary is-generate" data-studio-action="generate" ${s.submitting || (s.job && !StudioModel.terminal(s.job)) || (remix && !cap?.remix) ? 'disabled' : ''}>${i('spark')}<span>${s.submitting ? 'Starting…' : remix ? 'Remix image' : 'Generate image'}</span><kbd>${/Mac/.test(typeof navigator === 'undefined' ? '' : navigator.platform) ? '⌘' : 'Ctrl'} ↵</kbd></button>
      <p class="is-composer-foot">${remix ? 'Your original image stays untouched.' : 'Your creations are saved to your gallery.'}</p>
    </aside>`;
  }
  function reference(s) {
    const src = s.remix.source;
    return `<div class="is-field"><div class="is-label-row"><label for="is-remix-upload">Reference image</label>${src ? act('remove-reference','Remove','is-text-button') : ''}</div>${src ? `<div class="is-reference"><img src="${e(src.url)}" alt="Reference for your remix"><div><b>${e(src.name || 'Selected image')}</b>${act('choose-remix','Replace image','is-text-button')}</div></div>` : `<div class="is-dropzone is-dropzone-small" data-studio-drop="remix">${i('image')}<p>Give your idea a starting point.</p>${act('choose-remix',`${i('upload')} Choose image`,'is-button')}<small>JPG, PNG, WEBP · up to 20 MB</small>${s.assets.length ? act('choose-reference','Or choose from your gallery','is-text-button') : ''}</div>`}<input type="file" id="is-remix-upload" class="is-sr-only" accept="image/png,image/jpeg,image/webp" data-studio-upload="remix" tabindex="-1"></div>`;
  }
  function error(message) {
    return message ? `<p class="is-error" role="alert">${i('help')}<span>${e(message)}</span></p>` : '';
  }
  function status(s) {
    if (!s.job) return '';
    const job = s.job, done = StudioModel.terminal(job);
    if (job.status === 'completed') return '';
    const title = job.status === 'queued' ? 'Waiting in the queue' : job.status === 'processing' ? 'Creating your image' : job.status === 'cancelled' ? 'Generation cancelled' : 'Something interrupted this image';
    const elapsed = Math.max(0,Math.floor((Date.now()-Date.parse(job.startedAt || job.createdAt || new Date().toISOString()))/1000));
    return `<section class="is-job ${done ? 'is-job-terminal' : ''}" aria-label="Generation status"><span class="is-job-mark ${done ? '' : 'is-breathing'}">${i(done ? 'help' : 'spark')}</span><div><b role="status">${title}</b><p>${e(done ? job.error || 'Your draft is ready when you are.' : job.status === 'queued' ? 'You can keep exploring the studio.' : 'This can take a few minutes. Your previous image stays available.')}</p>${!done ? `<small data-studio-elapsed>${Math.floor(elapsed/60)}m ${elapsed%60}s elapsed</small>` : ''}</div>${done ? act('retry','Try again','is-button') : act('cancel','Cancel','is-button')}</section>`;
  }
  function assetActions(a) {
    const attrs = `data-id="${e(a.id)}"`;
    return act('copy',`${i('file')} Copy image`,'is-menu-item',attrs) + act('save',`${i('folder')} Save to Knowledge Hub`,'is-menu-item',attrs) + act('analyze-asset',`${i('eye')} Analyze image`,'is-menu-item',attrs) + act('reuse',`${i('history')} Reuse settings`,'is-menu-item',attrs) + act('details',`${i('sliders')} Image details`,'is-menu-item',attrs);
  }
  function canvas(s, remix = false) {
    const a = remix ? s.remix.result : s.assets.find(x => x.id === s.activeId);
    const source = remix ? s.remix.source : null;
    return `<section class="is-canvas-column" aria-label="Image preview"><div id="is-job-status">${status(s)}</div><div class="is-canvas-card">
      <div class="is-canvas-heading"><span>${a ? a.renderKind === 'vector-preview' ? 'VECTOR PREVIEW · ENGINE UNAVAILABLE' : 'YOUR CREATION' : remix ? 'A NEW PERSPECTIVE' : 'ROOM FOR IMAGINATION'}</span>${a ? `<small>${e(fileMeta(a))}</small>` : `<small>${remix ? 'Original → reimagined' : 'Preview'}</small>`}</div>
      ${a ? `${remix && source ? `<div class="is-compare-tabs" role="group" aria-label="Compare remix">${act('compare-original','Original',`is-button ${s.remix.compare === 'original' ? 'is-selected' : ''}`,`aria-pressed="${s.remix.compare === 'original'}"`)}${act('compare-result','Result',`is-button ${s.remix.compare === 'result' ? 'is-selected' : ''}`,`aria-pressed="${s.remix.compare === 'result'}"`)}</div>` : ''}<button type="button" class="is-artboard" data-studio-action="view" data-id="${e(a.id)}" aria-label="Expand image"><img src="${e(remix && s.remix.compare === 'original' ? source.url : a.url)}" alt="${e(remix && s.remix.compare === 'original' ? 'Original reference image' : a.prompt)}" width="${a.width}" height="${a.height}"><span class="is-expand-hint">${i('eye')} View image</span></button>
      <div class="is-canvas-toolbar"><span class="is-image-style">${i('image')} ${e(label(a.style))}</span><div><a class="is-button" href="${e(a.url)}" download="${e(StudioModel.filename(a))}">${i('download')} Download</a>${act('remix-asset',`${i('sliders')} Remix`,'is-button',`data-id="${e(a.id)}"`)}${menu(assetActions(a))}</div></div>
      <details class="is-image-details" id="is-image-details"><summary>Image details ${i('chevron')}</summary><p>${e(a.prompt)}</p><dl><div><dt>Format</dt><dd>${e(fileMeta(a))}</dd></div><div><dt>Seed</dt><dd>${e(a.seed)}</dd></div><div><dt>Created</dt><dd>${e(new Date(a.createdAt).toLocaleDateString())}</dd></div>${a.operation === 'remix' ? '<div><dt>Process</dt><dd>Image-to-image remix</dd></div>' : ''}</dl>${act('reuse','Reuse settings','is-text-button',`data-id="${e(a.id)}"`)}</details>` : `<div class="is-artboard is-artboard-empty"><div class="is-empty-art" aria-hidden="true"><span></span><span></span><span></span>${i('image')}</div><span class="is-eyebrow">${remix ? 'KEEP THE IDEA. CHANGE THE VIEW.' : 'FROM AN IDEA TO AN IMAGE'}</span><h2>${remix ? 'See where it takes you.' : 'What do you have in mind?'}</h2><p>${remix ? 'Add a reference and describe your changes. Your new image will appear here.' : 'Describe it in the prompt. Choose a style.<br>Let your imagination fill the canvas.'}</p></div>`}
      </div>${!remix && !s.assets.length && !s.create.prompt ? `<div class="is-starters"><span>Need a starting point?</span>${StudioModel.starters.map(([t,p],n) => act('starter',`${t} ${i('arrow')}`,'is-starter',`data-index="${n}"`)).join('')}</div>` : ''}
      ${!remix ? recent(s) : ''}</section>`;
  }
  function recent(s) {
    if (!s.assets.length) return '';
    return `<section class="is-recent"><div class="is-section-heading"><h2>Recent creations</h2>${act('gallery','View gallery '+i('arrow'),'is-text-button')}</div><div class="is-recent-strip">${s.assets.slice(0,8).map(a => act('preview',`<img src="${e(a.url)}" alt="${e(a.prompt)}" width="80" height="64" loading="lazy">`,'is-thumb',`data-id="${e(a.id)}" aria-label="Preview: ${e(a.prompt)}" aria-pressed="${s.activeId === a.id}"`)).join('')}</div></section>`;
  }
  function gallery(s) {
    return `<section class="is-gallery"><div class="is-gallery-heading"><div><h2>Your visual library</h2><p>Ideas you've brought to life, all in one place.</p></div>${act('create','Create an image '+i('plus'),'is-button')}</div><div class="is-gallery-tools"><label class="is-search">${i('search')}<input type="search" id="is-gallery-query" aria-label="Search your images" placeholder="Search by prompt or style…" value="${e(s.query)}" data-studio-field="query"></label><label class="is-filter"><span class="is-sr-only">Filter by style</span><select data-studio-field="filter" aria-label="Filter by style"><option value="all">All styles</option>${StudioModel.styles.map(([id,t]) => `<option value="${id}" ${s.filter === id ? 'selected' : ''}>${t}</option>`).join('')}</select></label>${act('select-mode',`${i('check')} ${s.selectionMode ? 'Done' : 'Select'}`,'is-button',`aria-pressed="${s.selectionMode}"`)}</div><div id="is-gallery-results">${galleryResults(s)}</div></section>`;
  }
  function galleryResults(s, choose = false) {
    const list = StudioModel.filterAssets(s.assets,s.query,s.filter);
    if (s.historyStatus === 'loading' && !s.assets.length) return `<div class="is-gallery-grid" aria-label="Loading images" aria-busy="true">${Array.from({length:6},()=>'<div class="is-skeleton"></div>').join('')}</div>`;
    if (s.historyStatus === 'error') return `<div class="is-empty-library">${i('help')}<h3>Your library couldn't load</h3><p>${e(s.historyError)}</p>${act('reload-history','Try again','is-button')}</div>`;
    return `${!choose && s.selected.size ? `<div class="is-selection-bar" role="region" aria-label="Selected image actions"><b>${s.selected.size} selected</b><div>${act('save-selected',i('folder')+' Save to Hub','is-button')}${act('delete-selected',i('trash')+' Delete','is-button is-danger')}${act('deselect','Clear','is-text-button')}</div></div>` : ''}<p class="is-result-count" role="status">${list.length} image${list.length === 1 ? '' : 's'}${s.query || s.filter !== 'all' ? ' found' : ''}</p>
      ${list.length ? `<div class="is-gallery-grid">${list.map(a => `<article class="is-gallery-card ${s.selected.has(a.id) ? 'is-card-selected' : ''} ${s.selectionMode ? 'is-selecting' : ''}">${!choose ? `<label class="is-card-check"><input type="checkbox" data-studio-select="${e(a.id)}" aria-label="Select image: ${e(a.prompt)}" ${s.selected.has(a.id) ? 'checked' : ''}></label>` : ''}<button type="button" class="is-gallery-preview" data-studio-action="${choose ? 'reference-asset' : 'view'}" data-id="${e(a.id)}" aria-label="${choose ? 'Use as reference' : 'View image'}: ${e(a.prompt)}"><img src="${e(a.url)}" alt="${e(a.prompt)}" width="${a.width}" height="${a.height}" loading="lazy"></button><div class="is-card-caption"><p>${e(a.prompt)}</p><footer><span>${e(label(a.style))} <span>·</span> ${e(a.aspectRatio)}</span>${choose ? act('reference-asset','Use image','is-text-button',`data-id="${e(a.id)}"`) : menu(assetActions(a)+act('delete',i('trash')+' Delete image','is-menu-item is-danger',`data-id="${e(a.id)}"`))}</footer></div></article>`).join('')}</div>` : `<div class="is-empty-library">${i('image')}<h3>${s.query || s.filter !== 'all' ? 'No images match just yet.' : 'A home for your next great idea.'}</h3><p>${s.query || s.filter !== 'all' ? 'Try another search or clear your filters.' : 'Create your first image and find it here.'}</p>${act(s.query || s.filter !== 'all' ? 'clear-filters' : 'create',s.query || s.filter !== 'all' ? 'Clear filters' : 'Create an image','is-button')}</div>`}`;
  }
  function analyze(s) {
    const a = s.analyze;
    const examples = [['Telecom tower','assets/example-tower.png'],['Data center','assets/example-datacenter.png'],['Satellite map','assets/example-map.png']];
    return `<section class="is-analyze"><div class="is-gallery-heading"><div><h2>A closer look.</h2><p>Explore an image, understand its details, and inspect visible text.</p></div></div>${a.source ? `<div class="is-analysis-layout"><section class="is-analysis-source"><div class="is-section-heading"><h3>Your image</h3>${act('choose-analyze','Replace','is-text-button')}${act('remove-analysis','Remove','is-text-button')}</div><img src="${e(a.source.url)}" alt="Selected image for analysis"><p>${e(a.source.name || 'Selected image')}</p>${a.example ? '<span class="is-example-label">Example image · analysis is generated on request</span>' : ''}${act('analyze',i('spark')+(a.loading ? ' Analyzing…' : ' Analyze image'),'is-primary',a.loading ? 'disabled' : '')}</section><section class="is-analysis-report" aria-busy="${a.loading}"><div class="is-section-heading"><h3>Image report</h3>${a.result ? act('copy-report',i('file')+' Copy','is-text-button') : ''}</div>${error(a.error)}${a.loading ? '<div class="is-report-placeholder"><span class="is-breathing">'+i('spark')+'</span><h3>Taking a closer look…</h3><p>Your report will appear here.</p></div>' : a.result ? `<span class="is-analysis-kind">${a.kind === 'metadata' ? 'File and metadata inspection · not visual recognition or OCR' : 'AI visual analysis · review for accuracy'}</span><div class="is-report-body">${renderMarkdown(a.result)}</div>${act('clear-report','Clear report','is-text-button')}` : '<div class="is-report-placeholder">'+i('eye')+'<h3>Every image has a story.</h3><p>Select Analyze image to explore this one.</p></div>'}</section></div>` : `<div class="is-dropzone is-analysis-dropzone" data-studio-drop="analyze"><span class="is-upload-mark">${i('upload')}</span><h3>Bring an image into focus.</h3><p>Drop it here, or choose a file to get started.</p>${act('choose-analyze',i('plus')+' Choose image','is-primary')}<small>JPG, PNG, WEBP · up to 20 MB</small></div>${error(a.error)}<div class="is-analysis-secondary">${act('url',i('link')+' Use an image URL','is-text-button')}<span>or explore an example</span><div class="is-examples">${examples.map(([t,url]) => act('example',`<img src="${url}" width="48" height="40" alt=""><span>${t}</span>${i('arrow')}`,'is-example',`data-url="${url}" data-name="${t}"`)).join('')}</div></div>`}<input type="file" id="is-analyze-upload" class="is-sr-only" accept="image/png,image/jpeg,image/webp" data-studio-upload="analyze" tabindex="-1"></section>`;
  }
  function body(s) {
    return `<section id="is-panel" role="tabpanel" aria-labelledby="is-tab-${s.tab}" tabindex="0">${s.tab === 'gallery' ? gallery(s) : s.tab === 'analyze' ? analyze(s) : `<div class="is-create-layout"><div id="is-editor">${editor(s,s.tab === 'remix')}</div><div id="is-canvas">${canvas(s,s.tab === 'remix')}</div></div>`}</section>`;
  }
  function render(s) { return `<div id="premium-studio" class="image-studio">${header(s)}${body(s)}<div class="is-sr-only" id="is-announcement" role="status" aria-live="polite"></div></div>`; }
  return {e, i, act, menu, label, fileMeta, header, editor, canvas, error, status, galleryResults, analyze, body, render};
})();
